'use strict';
const {randomUUID:uuid}=require('node:crypto');
module.exports=async function populate(f){
 const {db,workspace:w,inventory:i,owner:u,water,staff,till}=f;
 const customer=uuid(),sale=uuid(),line=uuid(),booking=uuid(),order=uuid(),delivery=uuid(),ret=uuid(),waste=uuid();
 const q=(sql,args)=>db.query(sql,args);
 const session=(await q('SELECT id FROM retail_till_sessions WHERE inventory_id=$1 LIMIT 1',[i])).rows[0].id;
 await q("INSERT INTO retail_customers(id,workspace_id,inventory_id,name,email,card_token)VALUES($1,$2,$3,'Test customer','customer@example.test',$4)",[customer,w,i,uuid()]);
 await q("INSERT INTO retail_sales(id,workspace_id,inventory_id,reference,total_pence,tendered_pence,change_pence,payment_method,actor_id,customer_id,registered_till_id,till_session_id)VALUES($1,$2,$3,'RT-BACKUP',300,300,0,'cash',$4,$5,$6,$7)",[sale,w,i,u,customer,till,session]);
 await q("INSERT INTO retail_sale_items(id,workspace_id,inventory_id,sale_id,product_id,name,barcode,qty,unit_price_pence,unit_cost_pence)VALUES($1,$2,$3,$4,$5,'Water','WATER',1,300,100)",[line,w,i,sale,water.id]);
 await q("INSERT INTO retail_returns(id,workspace_id,inventory_id,sale_id,reference,reason,total_pence,goods_pence,net_pence,vat_pence,registered_till_id)VALUES($1,$2,$3,$4,'RR-BACKUP','Test',300,300,300,0,$5)",[ret,w,i,sale,till]);
 await q("INSERT INTO retail_return_items(id,return_id,sale_item_id,product_id,name,qty,gross_pence,net_pence,vat_pence,restocked,cost_reversed_pence)VALUES($1,$2,$3,$4,'Water',1,300,300,0,true,100)",[uuid(),ret,line,water.id]);
 await q("INSERT INTO retail_loyalty_events(id,workspace_id,inventory_id,customer_id,sale_id,delta,kind)VALUES($1,$2,$3,$4,$5,1,'sale')",[uuid(),w,i,customer,sale]);
 await q("INSERT INTO retail_bookings(id,workspace_id,inventory_id,product_id,staff_id,customer_id,customer_name,duration_minutes)VALUES($1,$2,$3,$4,$5,$6,'Test customer',30)",[booking,w,i,water.id,staff.id,customer]);
 await q("INSERT INTO retail_reminders(id,workspace_id,inventory_id,booking_id,booking_version,payload,status)VALUES($1,$2,$3,$4,0,'{}','sent')",[uuid(),w,i,booking]);
 await q("INSERT INTO retail_preorders(id,workspace_id,inventory_id,customer_id,customer_name,collection_at,fulfilment)VALUES($1,$2,$3,$4,'Test customer',now(),'stock')",[order,w,i,customer]);
 await q("INSERT INTO retail_preorder_items(id,workspace_id,inventory_id,preorder_id,product_id,name,qty,unit_price_pence)VALUES($1,$2,$3,$4,$5,'Water',2,300)",[uuid(),w,i,order,water.id]);
 await q("INSERT INTO retail_deposits(id,workspace_id,inventory_id,origin_type,origin_id,amount_pence,session_id)VALUES($1,$2,$3,'booking',$4,100,$5)",[uuid(),w,i,booking,session]);
 await q("INSERT INTO retail_deliveries(id,workspace_id,inventory_id,supplier)VALUES($1,$2,$3,'Test supplier')",[delivery,w,i]);
 await q("INSERT INTO retail_delivery_items(id,workspace_id,inventory_id,delivery_id,product_id,ordered_qty,unit_cost_pence)VALUES($1,$2,$3,$4,$5,10,100)",[uuid(),w,i,delivery,water.id]);
 await q("INSERT INTO retail_waste_batches(id,workspace_id,inventory_id,registered_till_id,receipt)VALUES($1,$2,$3,$4,'{}')",[waste,w,i,till]);
 await q("INSERT INTO retail_waste(id,workspace_id,inventory_id,product_id,name,qty,unit_cost_pence,reason,batch_id)VALUES($1,$2,$3,$4,'Water',1,100,'damaged',$5)",[uuid(),w,i,water.id,waste]);
 await q("INSERT INTO retail_cash_events(id,workspace_id,inventory_id,session_id,kind,amount_pence,sale_id)VALUES($1,$2,$3,$4,'sale',300,$5)",[uuid(),w,i,session,sale]);
 await q("INSERT INTO retail_tasks(id,workspace_id,inventory_id,title)VALUES($1,$2,$3,'Test task')",[uuid(),w,i]);
 await q("INSERT INTO retail_reports(id,workspace_id,inventory_id,report_date,data)VALUES($1,$2,$3,current_date,'{}')",[uuid(),w,i]);
 await q("INSERT INTO retail_offers(id,workspace_id,inventory_id,name,kind,rule)VALUES($1,$2,$3,'Test offer','percent','{}')",[uuid(),w,i]);
 await q("INSERT INTO retail_reductions(id,workspace_id,inventory_id,product_id,reduced_price_pence,starts_at,ends_at)VALUES($1,$2,$3,$4,100,now(),now()+interval '1 day')",[uuid(),w,i,water.id]);
 await q("INSERT INTO retail_supplier_products(product_id,workspace_id,inventory_id)VALUES($1,$2,$3)",[water.id,w,i]);
 await q("INSERT INTO retail_price_reviews(id,workspace_id,inventory_id,product_id,baseline_cost_pence,latest_cost_pence,old_sale_pence,supplier_url)VALUES($1,$2,$3,$4,100,120,300,'https://example.test/item')",[uuid(),w,i,water.id]);
 await q("INSERT INTO retail_receipt_emails(id,workspace_id,inventory_id,sale_id,request_id,email,payload,created_at,next_attempt_at,status,sent_at)VALUES($1,$2,$3,$4,$5,'customer@example.test','{}',now(),now(),'sent',now())",[uuid(),w,i,sale,uuid()]);
 await q("INSERT INTO retail_reorder_emails(inventory_id,report_date,items,idempotency_key,status)VALUES($1,current_date,'[]','test','sent')",[i]);
};
